def text(s,x,y,size=18,color=INK,maxw=None):
    s=str(s).translate(str.maketrans({'→':'>','−':'-','▾':'(เลือก)','✓':'ผ่าน'}))
    if maxw:
        while pdfmetrics.stringWidth(s,'Thai',size)>maxw and size>11: size-=.5
    c.setFont('Thai',size);c.setFillColor(HexColor(color));c.drawString(x,H-y-size*.82,shapeStr(s,'Thai',size,force=True))
def rect(x,y,w,h,fill=WHITE,stroke=LINE,r=7):
    c.setFillColor(HexColor(fill));c.setStrokeColor(HexColor(stroke));c.setLineWidth(.8)
    c.roundRect(x,H-y-h,w,h,r,fill=1,stroke=fill!=stroke)
def line(x,y,x2,y2):
    c.setStrokeColor(HexColor(LINE));c.setLineWidth(.8);c.line(x,H-y,x2,H-y2)
def button(label,x,y,w=170,primary=False):
    rect(x,y,w,40,BROWN if primary else WHITE,BROWN if primary else LINE,5)
    text(label,x+14,y+12,15,WHITE if primary else BROWN,w-28)
def badge(label,x,y,w=112):
    rect(x,y,w,28,TINT,TINT,4);text(label,x+10,y+7,13,BROWN,w-20)
