    rect(0,0,W,H,BG,BG,0)
    text('haris',48,24,27,BROWN);text('Payroll / Wireframe',145,32,15,MUTED)
    text(role,1120,30,16,BROWN,270)
    rect(40,85,1360,715,WHITE,LINE,10)
    rect(40,85,225,715,'#FDFCFA',LINE,10)
    text('haris',63,111,30,BROWN);text('บุคคลและเงินเดือน',63,153,13,MUTED)
    text(role,63,195,16,BROWN,175)
    scope={'พนักงาน':'ข้อมูลของตัวเอง','หัวหน้าแผนก':'ครัวร้อน / สาขาสยาม','ผู้จัดการสาขา':'สาขาสยาม','HR / บัญชี':'ทุกสาขา','เจ้าของ':'ทุกสาขา / อ่านอย่างเดียว'}.get(role,'หน้าร่วม')
    text(scope,63,222,12,MUTED,175)
    for i,label in enumerate(NAV.get(role,['เข้าสู่ระบบ','ติดต่อ HR'])):
        y=265+i*34
        if label==active:rect(55,y-4,195,31,TINT,TINT,4)
        text(label,68,y+4,14,BROWN if label==active else MUTED,175)
    line(265,145,1400,145);text('พื้นที่ทำงาน / '+title,292,108,14,MUTED,870)
    text(title,302,178,27,INK,790);text(subtitle,302,219,15,MUTED,990)
    if cta: button(cta,1178,174,188,True)
    text(note,48,823,15,MUTED,1320)
    text('Static mockup · ไม่มีปุ่มหรือระบบทำงานจริง',48,862,12,MUTED)
