def finish():c.showPage()
def tabs(labels,active=0,y=260):
    x=302
    for i,s in enumerate(labels):
        w=min(230,max(100,pdfmetrics.stringWidth(s,'Thai',15)+28))
        if i==active:rect(x,y,w,35,TINT,TINT,4)
        text(s,x+12,y+10,15,BROWN if i==active else MUTED,w-24);x+=w+8
    line(302,y+44,1366,y+44)
def fields(items,y=285,x=302,w=1038):
    cw=(w-28)/2
    for i,item in enumerate(items):
        label,value=item[:2];xx=x+(i%2)*(cw+28);yy=y+(i//2)*82
        text(label,xx,yy,14,MUTED,cw)
        rect(xx,yy+25,cw,43);text(value or 'กรอกข้อมูล',xx+13,yy+38,16,INK if value else '#867A71',cw-26)
def table(cols,rows,y=340,x=302,w=1064,widths=None,rowh=47):
    widths=widths or [w/len(cols)]*len(cols)
    scale=w/sum(widths);widths=[v*scale for v in widths]
    rect(x,y,w,40,TINT,TINT,4)
    xx=x
    for i,s in enumerate(cols):text(s,xx+12,y+12,14,BROWN,widths[i]-24);xx+=widths[i]
    for n,row in enumerate(rows):
        yy=y+40+n*rowh
        xx=x
        for i,s in enumerate(row):text(s,xx+12,yy+16,16,INK,widths[i]-24);xx+=widths[i]
        line(x,yy+rowh,x+w,yy+rowh)
def toolbar(y=285,search='ค้นหาชื่อ หรือรหัสพนักงาน',scope=True):
    rect(302,y,390,40);text(search,318,y+12,14,MUTED,350)
    if scope:button('สาขา: ทุกสาขา' if current_role in ['HR / บัญชี','เจ้าของ'] else 'ข้อมูลของฉัน' if current_role=='พนักงาน' else 'สยาม / ครัวร้อน' if current_role=='หัวหน้าแผนก' else 'สาขา: สยาม',714,y,190)
    button('เดือน: ก.ย. 2569',926,y,207)
def notice(s,y=705,x=302,w=1064):
    rect(x,y,w,49,TINT,TINT,5);text(s,x+16,y+17,15,BROWN,w-32)
def detail_pairs(items,y=284,x=302,w=1038):
    for i,(a,b) in enumerate(items):
        yy=y+i*48;text(a,x,yy,15,MUTED,w*.35);text(b,x+w*.36,yy,17,INK,w*.6);line(x,yy+32,x+w,yy+32)
def listpage(role,title,active,cols,rows,cta=None,note='',subtitle='กันยายน 2569',tabs_=None):
    start(role,title,subtitle,active,note or 'ตัวอย่างหน้ารายการ / เลือกรายการเพื่อเปิดรายละเอียด',cta)
    if tabs_:tabs(tabs_);toolbar(319);table(cols,rows,378)
    else:toolbar();table(cols,rows)
    text(f'แสดง {len(rows)} รายการ',316,663,13,MUTED)
    button('ก่อนหน้า',1155,657,100);button('ถัดไป',1266,657,100)
    finish()
def formpage(role,title,active,items,note='',action='บันทึก',subtitle='ข้อมูลตัวอย่างสำหรับแสดงตำแหน่งของฟอร์ม'):
    start(role,title,subtitle,active,note or 'ฟอร์มภาพนิ่ง / ยังไม่บันทึกข้อมูลจริง')
    fields(items);button('ยกเลิก',1052,718,135);button(action,1202,718,164,True);finish()

